{"path": "ranges.mjs", "content": "export function mergeRanges(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError('mergeRanges expects an array of [start, end] pairs');
  }

  const pairs = ranges.map((pair, index) => {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError(`ranges[${index}] must be a [start, end] pair`);
    }
    const [start, end] = pair;
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new TypeError(`ranges[${index}] bounds must be safe integers`);
    }
    if (start > end) {
      throw new TypeError(`ranges[${index}] start must not exceed end`);
    }
    return [start, end];
  });

  pairs.sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]));

  const output = [];
  for (const [start, end] of pairs) {
    const last = output[output.length - 1];
    if (last !== undefined && start <= last[1] + 1) {
      if (end > last[1]) last[1] = end;
    } else {
      output.push([start, end]);
    }
  }
  return output;
}
